const API=location.origin;const state={media:"video",mode:"reference",assets:[],seq:0,kf:{},editingRid:null,};let timer=null;let MODEL_LIMITS={};let currentModel="agnes-video-2.5-flash";const activePolls=new Map();const SESS_KEY="agnes_sessions_v1";const DELETED_KEY="agnes_deleted_v1";let sessions=[];let currentSessionId=null;let batchMode=false;let selIds=new Set();let deletedIds=new Set();function localLoadSessions(){try{const d=JSON.parse(localStorage.getItem(SESS_KEY)||"[]");return Array.isArray(d)?d:[];}catch(e){return[];}}
