async function _reclaimMedia(urls){const list=(urls||[]).filter(Boolean);if(!list.length)return null;try{const r=await fetch(API+"/api/media/reclaim",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({urls:list.slice(0,400)})});return r.ok?await r.json():null;}catch(e){return null;}}
