function fmtSessTime(ts){const d=new Date(ts),now=new Date();const p=n=>String(n).padStart(2,"0");if(d.toDateString()===now.toDateString())return`${p(d.getHours())}:${p(d.getMinutes())}`;return`${d.getMonth()+1}/${d.getDate()} ${p(d.getHours())}:${p(d.getMinutes())}`;}
function createSession(name){const id="s_"+Date.now().toString(36)+"_"+Math.random().toString(36).slice(2,6);const sess={id,name:name||`新会话 ${sessions.length+1}`,createdAt:Date.now(),messages:[]};sessions.unshift(sess);currentSessionId=id;saveSessions();renderSessionList();reloadStream();}
